import React, { useEffect, useRef, useState } from 'react';

export default function OpeningSection() {
  const [visible, setVisible] = useState(false);
  const ref = useRef();

  useEffect(() => {
    const obs = new IntersectionObserver(([e]) => {
      if (e.isIntersecting) setVisible(true);
    }, { threshold: 0.2 });
    if (ref.current) obs.observe(ref.current);
    return () => obs.disconnect();
  }, []);

  return (
    <section ref={ref} id="pembuka-section" style={{
      background: 'linear-gradient(180deg, #fdf0f8 0%, #fce8f5 100%)',
      padding: '80px 20px 60px',
      textAlign: 'center',
      minHeight: '100vh',
      display: 'flex',
      flexDirection: 'column',
      alignItems: 'center',
      justifyContent: 'center',
    }}>
      <style>{`
        @keyframes fadeUp {
          from { opacity: 0; transform: translateY(30px); }
          to { opacity: 1; transform: translateY(0); }
        }
        .opening-anim { opacity: 0; }
        .opening-anim.visible { animation: fadeUp 0.8s ease forwards; }
        .d1 { animation-delay: 0.1s; }
        .d2 { animation-delay: 0.3s; }
        .d3 { animation-delay: 0.5s; }
      `}</style>

      {/* Assalamualaikum */}
      <h2
        className={`opening-anim d1${visible ? ' visible' : ''}`}
        style={{
          fontFamily: "'Dancing Script', cursive",
          fontSize: 'clamp(2rem, 6vw, 3rem)',
          color: '#e91e8c',
          marginBottom: '24px',
        }}
      >
        Assalamu'alaikum
      </h2>

      {/* Bismillah */}
      <p
        className={`opening-anim d2${visible ? ' visible' : ''}`}
        style={{
          fontFamily: "'Amiri', serif",
          fontSize: 'clamp(1.5rem, 4vw, 2.2rem)',
          color: '#333',
          marginBottom: '32px',
          direction: 'rtl',
          lineHeight: 1.8,
        }}
      >
        بِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ
      </p>

      {/* Quran verse */}
      <p
        className={`opening-anim d3${visible ? ' visible' : ''}`}
        style={{
          fontFamily: "'Poppins', sans-serif",
          fontSize: 'clamp(0.85rem, 2.5vw, 1rem)',
          color: '#555',
          maxWidth: '700px',
          lineHeight: 1.9,
          marginBottom: '12px',
        }}
      >
        Wahai manusia! Bertakwalah kepada Tuhanmu yang telah menciptakan kamu dari diri yang
        satu (Adam), dan (Allah) menciptakan pasangannya (Hawa) dari (diri)-nya; dan dari keduanya
        Allah memperkembangbiakkan laki-laki dan perempuan yang banyak. Bertakwalah kepada
        Allah yang dengan nama-Nya kamu saling meminta, dan (peliharalah) hubungan
        kekeluargaan. Sesungguhnya Allah selalu menjaga dan mengawasimu.
      </p>

      <p
        className={`opening-anim d3${visible ? ' visible' : ''}`}
        style={{
          fontFamily: "'Poppins', sans-serif",
          fontSize: '0.9rem',
          color: '#888',
          marginBottom: '20px',
          fontStyle: 'italic',
        }}
      >
        (QS. An-Nisa' (4) : 1)
      </p>
    </section>
  );
}
